import{f as r,ag as a,o as l,s as o}from"./chunks/framework.D85dHE_g.js";const b=JSON.parse('{"title":"安全生产法律法规","description":"","frontmatter":{},"headers":[],"relativePath":"关于工作/注册安全/安全生产法律法规.md","filePath":"关于工作/注册安全/安全生产法律法规.md","lastUpdated":1789128693000}'),e={name:"关于工作/注册安全/安全生产法律法规.md"};function n(i,t,s,h,d,g){return a(),l("div",null,t[0]||(t[0]=[o(`<h1 id="安全生产法律法规" tabindex="-1">安全生产法律法规 <a class="header-anchor" href="#安全生产法律法规" aria-label="Permalink to &quot;安全生产法律法规&quot;">​</a></h1><h2 id="第一章-安全生产相关国家政策" tabindex="-1">第一章 安全生产相关国家政策 <a class="header-anchor" href="#第一章-安全生产相关国家政策" aria-label="Permalink to &quot;第一章 安全生产相关国家政策&quot;">​</a></h2><h3 id="_1-领导人讲话与相关文件" tabindex="-1">1.领导人讲话与相关文件 <a class="header-anchor" href="#_1-领导人讲话与相关文件" aria-label="Permalink to &quot;1.领导人讲话与相关文件&quot;">​</a></h3><ol><li>坚持以人民为中心</li></ol><p><strong>依法保障人民权益</strong></p><ol start="2"><li>安全生产红线</li></ol><p><strong>不能牺牲人民的生命</strong></p><ol start="3"><li>20大报告指出安全治理模式向<strong>事前预防</strong>转型</li></ol><h3 id="_2-有关安全生产的重要文件" tabindex="-1">2.有关安全生产的重要文件 <a class="header-anchor" href="#_2-有关安全生产的重要文件" aria-label="Permalink to &quot;2.有关安全生产的重要文件&quot;">​</a></h3><ol><li><strong>党政主要负责人</strong>是本地区<strong>安全生产第一责任人</strong></li><li>地方各级安委员会的<strong>主任</strong>由<strong>政府的主要负责人</strong>来担任</li><li><strong>谁管谁负责</strong>：企业全员安全生产由<strong>单位全面责任</strong>；企业全员生产安全生产责任由法定代表人和实际控制人共同安全生产第一责任人</li><li>高危项目实行一票否决</li><li>一般隐患、<strong>重大隐患</strong>企业职代会实行‘<strong>双报告</strong>’制度向<strong>负有安全生产职责的部门</strong></li><li><strong>企业</strong>富有安全责任、管理、投入、培训和应急救援‘五到位’</li><li>宣传‘七进’：进企业、进学校、进机关、进社区、进农村、进家庭、进公共场所</li></ol><h2 id="第二章-法的形式及效力层级" tabindex="-1">第二章 法的形式及效力层级 <a class="header-anchor" href="#第二章-法的形式及效力层级" aria-label="Permalink to &quot;第二章 法的形式及效力层级&quot;">​</a></h2><h3 id="_1-法的形式判别" tabindex="-1">1.法的形式判别 <a class="header-anchor" href="#_1-法的形式判别" aria-label="Permalink to &quot;1.法的形式判别&quot;">​</a></h3><blockquote><p>法律--法、民法典<br> 法规--条例、特别规定<br> 规章--规定、办法、实施细则</p></blockquote><p>行政法规和地方性法规：有地方的为地方性 规章和地方性规章</p><h3 id="_2-法的形式及制定部门与效力" tabindex="-1">2.法的形式及制定部门与效力 <a class="header-anchor" href="#_2-法的形式及制定部门与效力" aria-label="Permalink to &quot;2.法的形式及制定部门与效力&quot;">​</a></h3><blockquote><p>同一机关： 特别&gt;一般、新&gt;旧<br> 不同机关制定：上位法&gt;下位法</p></blockquote><p>①宪法&gt;法律&gt;行政法规和地方性法规<br> ②地方性法规&gt;地方政府规章<br> ③地方性法规=部门规章<br> ④部门规章=地方政府规章</p><h2 id="第三章-安全生产法" tabindex="-1">第三章 安全生产法 <a class="header-anchor" href="#第三章-安全生产法" aria-label="Permalink to &quot;第三章 安全生产法&quot;">​</a></h2><h3 id="_1-安全生产法的基本规定" tabindex="-1">1.安全生产法的基本规定 <a class="header-anchor" href="#_1-安全生产法的基本规定" aria-label="Permalink to &quot;1.安全生产法的基本规定&quot;">​</a></h3><h4 id="_1-1安全生产法适用范围及工作机制" tabindex="-1">1.1安全生产法适用范围及工作机制 <a class="header-anchor" href="#_1-1安全生产法适用范围及工作机制" aria-label="Permalink to &quot;1.1安全生产法适用范围及工作机制&quot;">​</a></h4><p>特殊：消防脚痛喝伏特加<br> 有规定按规定，无规定适用《安全生产法》</p><h4 id="_1-2主要负责人的职责" tabindex="-1">1.2主要负责人的职责 <a class="header-anchor" href="#_1-2主要负责人的职责" aria-label="Permalink to &quot;1.2主要负责人的职责&quot;">​</a></h4><p>生产经营单位全面负责<br> 安全生产费用：根据规定提取，传款专用</p><h4 id="_1-3政府职责-安全生产监管职责" tabindex="-1">1.3政府职责（安全生产监管职责） <a class="header-anchor" href="#_1-3政府职责-安全生产监管职责" aria-label="Permalink to &quot;1.3政府职责（安全生产监管职责）&quot;">​</a></h4><p>政府：监管、协调、解决（乡镇只有协助）<br> 工会：监督、提意见</p><h3 id="_2-生产经营单位的安全生产保障" tabindex="-1">2.生产经营单位的安全生产保障 <a class="header-anchor" href="#_2-生产经营单位的安全生产保障" aria-label="Permalink to &quot;2.生产经营单位的安全生产保障&quot;">​</a></h3><h4 id="_2-1主要负责人和安全管理人员的责任" tabindex="-1">2.1主要负责人和安全管理人员的责任 <a class="header-anchor" href="#_2-1主要负责人和安全管理人员的责任" aria-label="Permalink to &quot;2.1主要负责人和安全管理人员的责任&quot;">​</a></h4><p>主要负责人：</p><ul><li>建章立制</li><li>组织制定并实施：制定</li><li>安全生产投入有效实施</li><li>报告：及时、如实报告生产安全事故</li></ul><p>安全生产管理人员（或机构）</p><ul><li>组织或参与：拟定</li><li>组织开展：培训、记录</li><li>排查隐患、提建议</li><li>督促落实整改措施</li></ul><h4 id="_2-2安全管理机构与管理人员的配备" tabindex="-1">2.2安全管理机构与管理人员的配备 <a class="header-anchor" href="#_2-2安全管理机构与管理人员的配备" aria-label="Permalink to &quot;2.2安全管理机构与管理人员的配备&quot;">​</a></h4><ul><li><p>考点一<br> 定性：未孕建金矿--机构或专职<br> 定量：大于100--机构或专职、小于等于100专职或兼职</p><pre><code>注册安全工程师的配备：
危金矿--应当配备（拓展：任免需要告知负由安全监督部门、考核合格）
其他--鼓励
</code></pre></li><li><p>考点二<br><strong>安全管理人员</strong><br> 发现安全问题：处理--不能处理--本单位有关负责人<br> 发现安全重大隐患：及时报告（向负责人）--不处理--向负有相关安全部门报告</p></li></ul><h4 id="_2-3从业人员的教育培训" tabindex="-1">2.3从业人员的教育培训 <a class="header-anchor" href="#_2-3从业人员的教育培训" aria-label="Permalink to &quot;2.3从业人员的教育培训&quot;">​</a></h4><p>从业人员（所有）：单位对从业培训（需合格） 劳务派遣：劳务公司必要安全培训、用工单位对从业培训 实习生：从业培训</p><h4 id="_2-4建设项目的规定" tabindex="-1">2.4建设项目的规定 <a class="header-anchor" href="#_2-4建设项目的规定" aria-label="Permalink to &quot;2.4建设项目的规定&quot;">​</a></h4><ol><li>安全评价 危金矿：应当按照国家有关规定进行<strong>安全评价</strong></li><li>安全实施‘三同时’ 三同时：同时设计、同时施工和同时投入生产和使用</li></ol><p>估--概（设计）--预--结--决</p><ol start="3"><li>安全实施设计审查与验收</li></ol><table tabindex="0"><thead><tr><th>对象</th><th>设计</th><th>审查</th><th>施工</th><th>验收</th><th>监督核查</th></tr></thead><tbody><tr><td>危金矿</td><td>建设项目安全设施的<strong>设计人、设计单位</strong>应当对安全实施<strong>设计</strong>负责</td><td><strong>安全实施设计</strong>应当按照国家规定报<strong>有关部门审查，审查部门对审查人</strong>应当对审<strong>查结果负责</strong></td><td><strong>实施单位</strong>必须按照批准的施工，并对实施的<strong>工程质量</strong>负责</td><td>竣工使用前应当<strong>建设单位</strong>负责组织对安全设施进行验收，合格才能使用</td><td>安全监督职责部门应当对建设单位的验收和结果监督核查</td></tr></tbody></table><h4 id="_2-5危险物品、事故隐患、重大危险源的规定" tabindex="-1">2.5危险物品、事故隐患、重大危险源的规定 <a class="header-anchor" href="#_2-5危险物品、事故隐患、重大危险源的规定" aria-label="Permalink to &quot;2.5危险物品、事故隐患、重大危险源的规定&quot;">​</a></h4><p>要求：</p><ul><li>危险物品的标志 <blockquote><p>生产经营单位应当在有较大危险因素的生产经营场所和有关设施、设备上，设置明显的<strong>安全警示标志</strong> 。<br> ！针对<strong>危险+海特+矿特</strong>，由<strong>专业单位生产</strong>，取得<strong>安全使用证或安全标志</strong>，检测及机构负检测结果责。</p></blockquote></li><li>重大危险源的备案 <blockquote><p>建档：<strong>生产单位</strong>对重大危险源<strong>登记建档</strong>，定期检测、<strong>评估</strong>、监控，告知及紧急采取应急措施。 备案： 生产单位向（县级）有关<strong>部门备案</strong></p></blockquote></li></ul><p><em>单位建档，部门备案</em></p><ul><li>事故隐患 <blockquote><p>事前：生产单位建立<strong>安全风险分级管控</strong><br> 事中：落实生产安全事故隐患排查，及时发现并<strong>消除事故隐患</strong><br> 事后：事故隐患--<strong>从业人员通报</strong>，重大事故隐患--向生产监督部门和职工大会<strong>报告</strong>（双报告）</p></blockquote></li></ul><h4 id="_2-6员工宿舍与劳动防护用品" tabindex="-1">2.6员工宿舍与劳动防护用品 <a class="header-anchor" href="#_2-6员工宿舍与劳动防护用品" aria-label="Permalink to &quot;2.6员工宿舍与劳动防护用品&quot;">​</a></h4><p>员工宿舍：生产、存储、生活不得在一起 劳动防护用户：满足国标和行标，生产单位 危险作业现场： <strong>爆破、吊装、动火、临时用电</strong>（临吊火爆）及国家其他现场，安排<strong>专人</strong>进行<strong>现场安全管理</strong></p><h4 id="_2-7交叉作业、发包出租" tabindex="-1">2.7交叉作业、发包出租 <a class="header-anchor" href="#_2-7交叉作业、发包出租" aria-label="Permalink to &quot;2.7交叉作业、发包出租&quot;">​</a></h4><ul><li><p>交叉双方：<br> ① 应当<strong>签订安全生产管理协议，明确各自的职责</strong><br> ② 并<strong>指定专职</strong>进行安全检查</p></li><li><p>发包出租：<br> ① <strong>不得</strong>出租发包给<strong>不具备</strong>相关条件的<br> ② 责任：<strong>签协议</strong>或<strong>合同约定</strong><br> ③ 协调：<strong>生产单位</strong>对承租方统一<strong>协调、管理</strong></p></li></ul><h3 id="_3-从业人员的安全生产权利义务" tabindex="-1">3. 从业人员的安全生产权利义务 <a class="header-anchor" href="#_3-从业人员的安全生产权利义务" aria-label="Permalink to &quot;3. 从业人员的安全生产权利义务&quot;">​</a></h3><h4 id="_3-1-从业人员安全生产权利" tabindex="-1">3.1 从业人员安全生产权利 <a class="header-anchor" href="#_3-1-从业人员安全生产权利" aria-label="Permalink to &quot;3.1 从业人员安全生产权利&quot;">​</a></h4><p>生产单位--从业人员：</p><ul><li>依法购买<strong>工伤保险</strong>，不得签到免除责任。</li><li>保险机构对单位赔偿，预防及提供安全事故</li><li>安全责任保险：鼓励（高危强制：未孕建金矿+渔业）</li><li>人员：提意见、批评、拒绝违章紧急--采取可能的措施--撤离</li></ul><h4 id="_3-2-从业人员安全生产义务" tabindex="-1">3.2 从业人员安全生产义务 <a class="header-anchor" href="#_3-2-从业人员安全生产义务" aria-label="Permalink to &quot;3.2 从业人员安全生产义务&quot;">​</a></h4><ul><li>义务： 发现隐患上报领导，遵章守法，佩戴劳保</li></ul><h3 id="_4-安全生产的监督管理" tabindex="-1">4. 安全生产的监督管理 <a class="header-anchor" href="#_4-安全生产的监督管理" aria-label="Permalink to &quot;4. 安全生产的监督管理&quot;">​</a></h3><h4 id="_4-1-主管部门的监管职责" tabindex="-1">4.1 主管部门的监管职责 <a class="header-anchor" href="#_4-1-主管部门的监管职责" aria-label="Permalink to &quot;4.1 主管部门的监管职责&quot;">​</a></h4><p>主管部门职责：审查批准，验收&lt;证&gt; 权限：</p><ul><li>不批准：不合法、不合标准</li><li>取缔：未批准，擅自活动--举报，应<strong>取缔</strong></li><li>撤销：已批准，不具备，应<strong>撤销</strong></li><li>不收费，不指定</li></ul><h4 id="_4-2-监督检查" tabindex="-1">4.2 监督检查 <a class="header-anchor" href="#_4-2-监督检查" aria-label="Permalink to &quot;4.2 监督检查&quot;">​</a></h4><p>监察人员：（工贸企业+危+爆竹）</p><ul><li>现场检查：涉密可看，要保密</li><li>现场处置：违法行为--纠正，限期改正；个人200以下，单位3000元以下</li><li>紧急处理：事故--立即排除，<strong>重大事故隐患--无法保安全</strong>的--<strong>撤离</strong>--<strong>暂停</strong>生产--排出后经<strong>审查同意</strong>恢复</li><li>查封扣押：不符合</li></ul><p>安全检查要求：</p><ul><li>不影响生产</li><li>出示<strong>行政执法</strong>证件，&gt;=2人</li><li><strong>*书面记录</strong>，<strong>检查人与被检查负责人</strong>签字--被检查拒绝应<strong>记录在案</strong></li><li>联合检查，互通情况</li></ul><h4 id="_4-3-停电、惩戒" tabindex="-1">4.3 停电、惩戒 <a class="header-anchor" href="#_4-3-停电、惩戒" aria-label="Permalink to &quot;4.3 停电、惩戒&quot;">​</a></h4><ul><li>重大安全隐患，要求停业</li><li><strong>拒不执行</strong>企业，有<strong>现实危险</strong>，经<strong>部门负责人批准</strong>可通知停电 <blockquote><p>① 通过书面形式<br> ② <strong>提前24小时</strong></p></blockquote></li></ul><p>联合惩戒：<br><strong>有关部门和机构</strong>，对<strong>失信</strong>企业及从业人，采取加大<strong>检查频次、暂停审批、上调</strong>有关保费，或从业人<strong>禁入</strong>，向<strong>社会公示</strong></p><h4 id="_4-4-举报、公益诉讼" tabindex="-1">4.4 举报、公益诉讼 <a class="header-anchor" href="#_4-4-举报、公益诉讼" aria-label="Permalink to &quot;4.4 举报、公益诉讼&quot;">​</a></h4><p>举报：</p><ul><li><strong>任何单位和个人</strong>都可以举报</li><li>涉及<strong>死亡</strong>，由<strong>县级以上人民政府</strong>组织核查处理</li></ul><p>公益诉讼：<br> 造成<strong>重大事故隐患或导致重大事故</strong>，致<strong>国家利益或社会公共利益</strong>侵害，<strong>*人民检察院</strong>提起</p><h3 id="_5-生产安全事故的应急救援与调查处理" tabindex="-1">5.生产安全事故的应急救援与调查处理 <a class="header-anchor" href="#_5-生产安全事故的应急救援与调查处理" aria-label="Permalink to &quot;5.生产安全事故的应急救援与调查处理&quot;">​</a></h3><h4 id="_5-1-政府应急救援的职责" tabindex="-1">5.1 政府应急救援的职责 <a class="header-anchor" href="#_5-1-政府应急救援的职责" aria-label="Permalink to &quot;5.1 政府应急救援的职责&quot;">​</a></h4><p>国家：</p><ul><li>统一协调</li><li>鼓励建设<br> 县级以上人民政府：本行政区域 乡政人民政府：协助</li></ul><h4 id="_5-2-单位应急救援组织" tabindex="-1">5.2 单位应急救援组织 <a class="header-anchor" href="#_5-2-单位应急救援组织" aria-label="Permalink to &quot;5.2 单位应急救援组织&quot;">​</a></h4><ul><li>应急预案：<strong>生产经营单位</strong>，应当制定<strong>应急救援预案</strong>，与当地县级人民政府预案<strong>相衔接</strong>，并<strong>定期组织演练</strong></li><li>应急器材：<strong>未见到金矿</strong>应当配备及定期保养维护</li><li>应急组织：①<strong>未见到金矿</strong>+②生产规模较小（指定兼职应急救援人）</li></ul><h4 id="_5-3-事故报告" tabindex="-1">5.3 事故报告 <a class="header-anchor" href="#_5-3-事故报告" aria-label="Permalink to &quot;5.3 事故报告&quot;">​</a></h4><p>民报民：立即（领导）<br> 民报官：1小时（事故当地县级以上人民政府应急部门和有关富有安全职责部门）<br> 官报官：2小时</p><p>事故救援：</p><ul><li>政府、应急--立即赶现场，组织抢救</li><li>单位、个人--支持配合，提供便利</li></ul><h3 id="_6-法律责任" tabindex="-1">6.法律责任 <a class="header-anchor" href="#_6-法律责任" aria-label="Permalink to &quot;6.法律责任&quot;">​</a></h3><h4 id="_6-1-技术服务机构的法律责任" tabindex="-1">6.1 技术服务机构的法律责任 ** <a class="header-anchor" href="#_6-1-技术服务机构的法律责任" aria-label="Permalink to &quot;6.1 技术服务机构的法律责任 \\*\\*&quot;">​</a></h4><ul><li>失实报告：停业、3~10W罚款</li><li>租借、挂靠、虚假报告： <blockquote><ol><li>① 没收违法所得 ② 罚款：违法所得在<strong>10W以上，罚2~5倍</strong>；<strong>不足10W，罚10~20W</strong> ③ 连带责任</li><li>直接<strong>责任主管和其他责任人，5~10W</strong></li><li>机构、人员<strong>吊销</strong>资质（格），<strong>5年内</strong>不从事，<strong>情节严重</strong>终身不得从事</li></ol></blockquote></li></ul><h4 id="_6-2-人员的法律责任" tabindex="-1">6.2 人员的法律责任 *** <a class="header-anchor" href="#_6-2-人员的法律责任" aria-label="Permalink to &quot;6.2 人员的法律责任 \\*\\*\\*&quot;">​</a></h4><p>安全费用投入不够：</p><blockquote><p>未发生事故：限期改正，<strong>逾期</strong>停业停产整顿<br> 发生事故：个人经营投资人罚<strong>2~20W</strong> 上一年收入：40%（一般）、60%（较大）、80%（重大）、100%（特别重大）<br> 刑事责任：自刑罚执行起<strong>5年</strong>内不得担任<strong>任何</strong>生产单位的主要负责人，对于<strong>重大、特别重大</strong>的<strong>终生</strong>的不得主要责任人</p></blockquote><blockquote><p>安全事故规定：2W~5W（一般）5W~10W(较大)10W~15W(重大)15W~20W(特别重大)</p></blockquote><p>主要负责人没有参与或擅离职守、逃匿（安全生产法）：</p><ol><li>降级、撤职</li><li>**60%~100%**的上一年收入罚款</li><li><strong>逃匿</strong>的处15日以下的<strong>拘留</strong></li><li>构成犯罪的，追究刑事责任</li><li>隐瞒不报、谎报、迟报按以上处罚</li></ol><blockquote><p>安全生产条例：轻（迟、漏报、擅离职守）40%~80%，重（谎、瞒、伪造、转移、隐匿、拒绝、逃匿）：60%~100%，且单位100W~500W</p></blockquote><p>其他责任人和安全责任人（安全法）：<br> 生产管理人员未履行职责：暂停或吊销有关资格，并处**20%~50%**上一年收入的罚款</p><blockquote><p>安全事故规定：20%~30%（一般）30%~40%(较大)40%~50%(重大)<br> 事故等级：1-2人（一般）3-9（较大）10-29（重大）30及以上（特别重大）</p></blockquote><h4 id="_6-3-单位的法律责任" tabindex="-1">6.3 单位的法律责任 ** <a class="header-anchor" href="#_6-3-单位的法律责任" aria-label="Permalink to &quot;6.3 单位的法律责任 \\*\\*&quot;">​</a></h4><ul><li>生产单位未发生事故：</li></ul><table tabindex="0"><thead><tr><th></th><th>单位</th><th>初次(万元)</th><th>逾期(万元)</th><th>责任人</th><th>初次(万元)</th><th>逾期（万元）</th></tr></thead><tbody><tr><td>设备设施</td><td>单位</td><td>5以下</td><td>5～20</td><td>责任人</td><td></td><td>1～2</td></tr><tr><td>管理</td><td>单位</td><td>10以下</td><td>10～20</td><td>责任人</td><td></td><td>2～5</td></tr><tr><td>审核</td><td>单位</td><td>10～50</td><td>50～100</td><td>责任人</td><td>2～5</td><td>5～10</td></tr></tbody></table><ul><li>生产单位发生事故：30W~100W~200W~1000W~2000W</li></ul><p>事故判断表格：</p><table tabindex="0"><thead><tr><th style="text-align:center;">判定指标</th><th style="text-align:center;">一般事故</th><th style="text-align:center;">较大事故</th><th style="text-align:center;">重大事故</th><th style="text-align:center;">特别重大事故</th></tr></thead><tbody><tr><td style="text-align:center;">死亡人数</td><td style="text-align:center;">&lt;3人</td><td style="text-align:center;">3~9人</td><td style="text-align:center;">10~29人</td><td style="text-align:center;">≥30人</td></tr><tr><td style="text-align:center;">重伤人数</td><td style="text-align:center;">&lt;10人</td><td style="text-align:center;">10~49人</td><td style="text-align:center;">50~99人</td><td style="text-align:center;">≥100人</td></tr><tr><td style="text-align:center;">直接经济损失</td><td style="text-align:center;">&lt;1000万元</td><td style="text-align:center;">1000万~5000万元</td><td style="text-align:center;">5000万~1亿元</td><td style="text-align:center;">≥1亿元</td></tr></tbody></table><h2 id="第四章-安全生产单行法律" tabindex="-1">第四章 安全生产单行法律 <a class="header-anchor" href="#第四章-安全生产单行法律" aria-label="Permalink to &quot;第四章 安全生产单行法律&quot;">​</a></h2><h3 id="_1-消防法" tabindex="-1">1. 消防法 * <a class="header-anchor" href="#_1-消防法" aria-label="Permalink to &quot;1. 消防法 \\*&quot;">​</a></h3><h4 id="_1-1-基本规定" tabindex="-1">1.1 基本规定 <a class="header-anchor" href="#_1-1-基本规定" aria-label="Permalink to &quot;1.1 基本规定&quot;">​</a></h4><p>消防验收：住建部--建设部门，其他--备案等抽查 消防检查：</p><ul><li>告知：投用前在<strong>建设单位或使用单位</strong>向当地县级人民政府<strong>消防机构</strong>申请<strong>消防安全检查</strong></li><li>不告知：提取申请<strong>10个工作日内</strong>进行检查</li></ul><p>一般单位的消防安全职责：<strong>每年至少一次</strong>全面检测</p><p>消防安全重点单位的安全职责：</p><ul><li>县级以上地方政府<strong>消防救援机构</strong>对有可能发生重大单位，并由<strong>应急管理部门</strong>报<strong>本级人民政府备案</strong>。</li><li>履行：人定巡档--①确<strong>定</strong>安全管理<strong>人</strong>②<strong>建</strong>立消防档案③<strong>每日防火巡查</strong>④<strong>定期</strong>组织演练</li></ul><h4 id="_1-2-消防组织的规定" tabindex="-1">1.2 消防组织的规定 <a class="header-anchor" href="#_1-2-消防组织的规定" aria-label="Permalink to &quot;1.2 消防组织的规定&quot;">​</a></h4><p>消防队伍的建立：</p><ul><li>政府： 县级以上--应当建立，乡镇--根据当地经济发展或需要</li><li>单位： 一般--根据需要，高危--应当建立</li></ul><p>应建立专职消防队的单位：</p><ul><li>鹤岗非法（核电飞港）+ 危险&lt;大型、主要&gt;</li><li>可燃+重要</li></ul><h4 id="_1-3-灭火救援的规定" tabindex="-1">1.3 灭火救援的规定 <a class="header-anchor" href="#_1-3-灭火救援的规定" aria-label="Permalink to &quot;1.3 灭火救援的规定&quot;">​</a></h4><ul><li>县级政府：组织有关部门制定预案</li><li>火灾现场总指挥：停水电燃气、交通管制、拆除建筑、调动有关单位</li><li>单位：立即组织扑救</li><li>个人：立即报警、无偿提供<strong>报警</strong>便利 、耗损<strong>政府</strong>补</li></ul><h3 id="_2-交通安全法" tabindex="-1">2. 交通安全法 <a class="header-anchor" href="#_2-交通安全法" aria-label="Permalink to &quot;2. 交通安全法&quot;">​</a></h3><ul><li><strong>道路主管部门+公安机关交通管理部门</strong></li><li>高速拦车：只有公安执行公务</li></ul><h3 id="_3-特种设备安全法" tabindex="-1">3. 特种设备安全法 <a class="header-anchor" href="#_3-特种设备安全法" aria-label="Permalink to &quot;3. 特种设备安全法&quot;">​</a></h3><h4 id="_3-1-特种设备的生产" tabindex="-1">3.1 特种设备的生产 <a class="header-anchor" href="#_3-1-特种设备的生产" aria-label="Permalink to &quot;3.1 特种设备的生产&quot;">​</a></h4><ul><li>特种设备的总则 <blockquote><p>范围：游客叉中电压力锅</p></blockquote></li><li>特种设备生产单位 <blockquote><p>设计文件要鉴定--游客杨锅瓶；实验【需要】--新产品、新材料、新部件</p></blockquote></li><li>特种设备的安装、改造、修理 <blockquote><p>施工前：施工单位向市级部门书面报告<br> 验收后：30日内向使用单位移交资料 电梯的安全性能--电梯制造单位负责</p></blockquote></li></ul><h4 id="_3-2-特种设备的经营" tabindex="-1">3.2 特种设备的经营 <a class="header-anchor" href="#_3-2-特种设备的经营" aria-label="Permalink to &quot;3.2 特种设备的经营&quot;">​</a></h4><p>销售单位：检查验收和销售记录制度<br> 出租单位：对使用管理和维护保养负责</p><h4 id="_3-3-特种设备的使用" tabindex="-1">3.3 特种设备的使用 <a class="header-anchor" href="#_3-3-特种设备的使用" aria-label="Permalink to &quot;3.3 特种设备的使用&quot;">​</a></h4><p>设备管理：</p><ul><li><strong>*投入使用前</strong>或<strong>投入使用后三十日内</strong>向市级办理登记，取得<strong>使用登记证书</strong>，<strong>登记标志</strong>应至于该设备<strong>显著位置</strong></li><li>机构或专职：电梯、客运索道、大型游乐设施</li></ul><p>维护保养定期检验：</p><ul><li>使用单位：（每月至少一次） 、定期自行检查、故障\\异常--全面检查</li><li>出现问题：管理人员立即处理、作业人员报告</li><li>定期检验：有效期满前1个月提</li><li>客索、大型游乐设施：每日试运行、例行检查</li></ul><p>电梯：</p><ul><li>维护保养：制造单位、许可的单位（对其维护保养的电梯安全性能负责）</li><li>每15日一次清洁、润滑、调整和检查</li><li>跟踪调查了解：电梯制造到位</li><li>严重事故隐患：告知电梯使用单位</li></ul><h4 id="_3-4-特种设备的改造与报废" tabindex="-1">3.4 特种设备的改造与报废 <a class="header-anchor" href="#_3-4-特种设备的改造与报废" aria-label="Permalink to &quot;3.4 特种设备的改造与报废&quot;">​</a></h4><p>报废：原登记部门+注销<br> 继续使用： <strong>检验或安全评估</strong>+办理<strong>使用登记证书变更</strong></p><h4 id="_3-5-特种设备的检验、检测" tabindex="-1">3.5 特种设备的检验、检测 <a class="header-anchor" href="#_3-5-特种设备的检验、检测" aria-label="Permalink to &quot;3.5 特种设备的检验、检测&quot;">​</a></h4><p>机构+人员：严重事故隐患--告知单位、部门，不得推荐、监制<br> 人员：不得多机构执业</p><h4 id="_3-6-特种设备的监督管理" tabindex="-1">3.6 特种设备的监督管理 <a class="header-anchor" href="#_3-6-特种设备的监督管理" aria-label="Permalink to &quot;3.6 特种设备的监督管理&quot;">​</a></h4><ul><li>职权：现场检查、查阅 复印资料；严重隐患、报废--查封</li><li>2人以以上执法+行政执法证件</li><li>不得 要求单位重复取得许可证</li><li>检查情况：书面记录+检查人员、负责人签字</li></ul><h3 id="_4-建筑法" tabindex="-1">4. 建筑法 <a class="header-anchor" href="#_4-建筑法" aria-label="Permalink to &quot;4. 建筑法&quot;">​</a></h3><h3 id="_5-危险化学品安全法" tabindex="-1">5. 危险化学品安全法 <a class="header-anchor" href="#_5-危险化学品安全法" aria-label="Permalink to &quot;5. 危险化学品安全法&quot;">​</a></h3>`,136)]))}const c=r(e,[["render",n]]);export{b as __pageData,c as default};
